  const magic=buf.indexOf(Buffer.from([0x28,0xb5,0x2f,0xfd]),off);
  if(magic<0) break;
  const next=buf.indexOf(Buffer.from([0x28,0xb5,0x2f,0xfd]),magic+4);
  const end=next<0?buf.length:next;
  const frame=buf.subarray(magic,end);
  try{ chunks.push(z.zstdDecompressSync(frame)); }catch(e){ /* skip */ }
  off=end;
}
const all=Buffer.concat(chunks);
fs.writeFileSync(out,all);
